# Medición simple de diversidad sintética vs real (Distinct-2)
def distinct_n(texts, n=2):
    ngrams = [tuple(t.split()[i:i+n]) for t in texts for i in range(max(0, len(t.split())-n+1))]
    return len(set(ngrams)) / max(1, len(ngrams))

